CREATE COLUMN TABLE "TEST_AP"."DAR3" ("ArcEntry" INTEGER CS_INT NOT NULL , "Line_ID" INTEGER CS_INT NOT NULL , "DocType" NVARCHAR(20), "DocAbs" INTEGER CS_INT, "DocNum" INTEGER CS_INT, "DocSubType" NVARCHAR(2) DEFAULT '--', "PIndicator" NVARCHAR(10) DEFAULT ' ', PRIMARY KEY ("ArcEntry", "Line_ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."DAR3" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$DocType$DocSubType$DocNum$PIndicator$','DocType','DocSubType','DocNum','PIndicator'));
CREATE INDEX "DAR3_DOC_NUM" ON "TEST_AP"."DAR3" ( "DocType" ASC, "DocSubType" ASC, "DocNum" ASC, "PIndicator" ASC )